package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_value_TriageGen2Test {
    private JsonWriter jsonWriter;

    @Before
    public void init() throws IOException {
        Writer writer = new OutputStreamWriter(System.out);
        jsonWriter = new JsonWriter(writer);
    }

    @Test
    public void test_value_long() throws IOException {
        jsonWriter.value(123L);
        jsonWriter.flush();
        assertEquals("{\"value\":123}", jsonWriter.toString());
    }

    @Test
    public void test_value_long_Lenient() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(123L);
        jsonWriter.flush();
        assertEquals("{\"value\":123}", jsonWriter.toString());
    }

    @Test
    public void test_value_long_Nulls() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.value(123L);
        jsonWriter.flush();
        assertEquals("{\"value\":123}", jsonWriter.toString());
    }

    @Test
    public void test_value_long_HtmlSafe() throws IOException {
        jsonWriter.setHtmlSafe(true);
        jsonWriter.value(123L);
        jsonWriter.flush();
        assertEquals("{\"value\":123}", jsonWriter.toString());
    }

    @Test(expected = IOException.class)
    public void test_value_long_NullWriter() throws IOException {
        jsonWriter = new JsonWriter(null);
        jsonWriter.value(123L);
    }

    @Test
    public void test_value_long_SingleValue() throws IOException {
        jsonWriter.value(123L);
        assertEquals("{\"value\":123}", jsonWriter.toString());
    }

    @Test
    public void test_value_long_MultipleValues() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("value1");
        jsonWriter.value(123L);
        jsonWriter.name("value2");
        jsonWriter.value(456L);
        jsonWriter.endObject();
        jsonWriter.flush();
        assertEquals("{\"value1\":123,\"value2\":456}", jsonWriter.toString());
    }
}
